insert into public.theories (id, question_id, legacy_author_key, identity_mode, thesis, paragraphs, change_mind, status, dmz_pick, starter, needs_review, legacy_url, created_at, published_at) values
  ('l4030', 'what-makes-sex-taboo', 'nick-s', 'name', null, array['In our culture, death is taboo. Depression is taboo. Sex is taboo. Death is taboo because our entire culture is built around fear and denial of death and decay. Depression is taboo because we seek the light and fear the darkness within ourselves. Sex is taboo because we live in a hyper masculine culture that fetishes penetration – from sending rockets into space to waging war. We taboo what we don’t want to look at, what we fear, and what makes us uncomfortable, in both ourselves and society.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-5-4/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4131', 'what-makes-sex-taboo', 'chiron', 'name', null, array['Ideas, philosophies, dogmas. It is taboo only by man’s interpretation of what is taboo and what is not taboo. Otherwise, sex is a natural activity for integrating spirit into matter (Taurus), procreation (Leo), intimacy (Scorpio), elevation of consciousness (Aquarius). It is an activity to learn about how to use our creative energy which is our very life force. Because it is precious and delicate, humans are still learning how to use such energy and relate to sex.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-5-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5769', 'what-makes-sex-taboo', 'william-h', 'name', null, array['Sex often leads to babies. The number of people who want sex exceeds the number of people who are willing to take care of those babies. The taboo is a social device necessary to better align the number of babies with the number of people willing to take care of babies.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/what-makes-sex-taboo/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l4028', 'is-there-such-a-thing-as-unconditional-love', 'chiron', 'name', null, array['Unconditional love is unwavering and imperturbable. There is never a moment where one would question their love for someone who they love unconditionally. On the contrary, conditional love is usually tied to selfish desires. When our love is conditional, we fuse a person with our temporary pleasure, and form a fog of infatuation for them. This is only a facade, and this type of love is as fragile as a single candle flame. Unconditional love is as strong as a raging fire and the only true love that exists.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-2-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4026', 'is-there-such-a-thing-as-unconditional-love', 'eva-lenore', 'name', null, array['Unconditional love exists, but not in the ways we think. Love itself is the core of our existence – however, as humans we condition our experience of love based on attachments and a perceived sense of separateness. When we feel separate from others, there arises selfishness – and if there is any trace of selfishness within us, even if it is out of survival, the love that we experience is usually conditioned by this illusion. Thus, to awaken to our true nature is to discover unconditional love.”', '-The Kid']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-2-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4128', 'is-there-such-a-thing-as-unconditional-love', 'chiron', 'name', null, array['Unconditional love is not a thing. It is the very fabric that pervades life. It is the very nature of living and the original nature of having consciousness. It is the very existence. There can never be a conditional or ‘unconditional’ love – these are labels made up by the mind. If we live life existentially, we will always experience and be this essence of living and thus, loving. If we live life psychologically, we will always differentiate what is and what isn’t and never notice this essence of life.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-2-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4712', 'is-there-such-a-thing-as-unconditional-love', 'kai-b', 'name', null, array['Love can be unconditional, but its important to note that there is nothing truly wrong with conditional love. We all have preferences, that is natural, its a wonderful gift to get to love the people, places, and things that we conditionally love most. Of course, no person, place, or thing is perfect in a conditional sense so the greater the level of unconditional love, the more peace and joy it will bring us. Unconditional love is possible in that we can love someone or something just as it is, without needing it to change in anyway. But, that doesn’t mean we need to adhere to the demands of that someone or something in a self-sacrificing way. It just means we don’t need them to do or not do anything for us to love them. Unconditional and conditional love go together, there is no need to strive for perfect unconditional love for all, especially at the expense of our well-being. Love that is best in my eyes, is love that is nonjudgmental, free, and willing.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-2-4/', '2020-05-05T12:00:00Z', '2020-05-05T12:00:00Z'),
  ('l5591', 'is-there-such-a-thing-as-unconditional-love', 'miranda-d', 'name', null, array['That’s a good question and it’s hard to say, especially from me, who hasn’t really experienced any severe emotional trauma. For example, I would say that I unconditionally love my mother, or sibling, best friend or partner(s). But I wonder if any type of negative, abusive relationship would affect this ideal of ‘unconditionality.’ However, maybe this is being too specific. In the broader sense, I think that ‘unconditional love’ can exist when talking about, say, humanity. Or life itself. Or existence. I unconditionally love the human experience. Isn’t that tantra? Or, I unconditionally love the act of being alive. Isn’t this being present?']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/is-there-such-a-thing-as-unconditional-love/', '2020-05-24T12:00:00Z', '2020-05-24T12:00:00Z'),
  ('l4024', 'what-is-the-greatest-lesson-to-learn-from-heartbreak', 'n-bailey', 'name', null, array['Heartbreak allows us to be flexible and break mental habits of relying on the external world for our internal wellbeing. It allows us to accept impermanence. We get so comfortable in relationships, but they are guaranteed to end and heartbreak is inevitable. Whether you break up or you die is basically the same thing – you still have to let go.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-4-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4022', 'what-is-the-greatest-lesson-to-learn-from-heartbreak', 'nick-s', 'name', null, array['Few words bring up as visceral of a reaction as ‘heartbreak’. The feeling of having the heart ripped from the chest, leaving a painful void behind is palpable. Yet to undergo this process of loss is one of the most fertile and potent experiences we can have. Though painful, to emerge from heartbreak is to emerge with the empowerment and knowledge that what you thought you couldn’t live without, you can live without. From this realization comes a unique type of growth and freedom.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-4-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4126', 'what-is-the-greatest-lesson-to-learn-from-heartbreak', 'chiron', 'name', null, array['Impermanence of external circumstances on our life. Heartbreak does not truly mean our heart is broken, but refers to a feeling of loss and attachment to external circumstances. This immediately plummets us to a space of unknown and uncertainty because it interrupts what we had always known from past experiences. This is the moment of infinite possibilities to happen. Learn that in moments as such that we have a choice – to be miserable about our heartbreak or be joyful about our heartbreak.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-4-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4714', 'what-is-the-greatest-lesson-to-learn-from-heartbreak', 'kai-b', 'name', null, array['Heartbreak, along with the agony it carries, also carries innate gifts and lessons. Among the greatest is the gift of personal sovereignty and security. Heartbreak exposes our greatest insecurities, weaknesses, and fears. This is no fun for anyone, yet if we are brave enough and curious enough, these pains can be transmuted into profound levels of security, strength, and fearlessness. From here we have the potential to enter into a new relationship from our new ground, a ground of stable independence, allowing for a truly interdependent relationship. Heartbreak exposes our co-dependent, or dependent dynamics. It gives us the golden opportunity to face the truth, that we are ultimately alone here. When we become stable in this truth, joyous, balanced relationship becomes not only possible, but inevitable.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-4-4/', '2020-05-05T12:00:00Z', '2020-05-05T12:00:00Z'),
  ('l5801', 'what-is-the-greatest-lesson-to-learn-from-heartbreak', 'paul-h', 'name', null, array['Love can teach you a whole lot about life. But the best teacher is that of heartbreak. You don’t ever fully know what you have until you lose it and therefore can’t understand love until you’ve lost it. Heartbreak is life’s most effective teacher. Unfortunately, what it teaches us isn’t always accurate. We learn what we choose to interpret. There are, however, lessons that we should all take from falling into and out of love – lessons that are universal. If you learn these things from the ending of a loving relationship, then you should consider yourself to have made progress in your life. Here are 10 things love can teach us that nothing else truly can:', '1. Physical Pain Isn’t The Worst Kind Of Pain.', 'While physical pain can be unbearable, so can emotional pain. Emotional pain is often more dangerous than physical pain because unlike physical pain, we aren’t always entirely aware of our emotional distress. It can lie dormant or simply ignored for long stretches of time. It can then rush over us in a single wave, potentially overwhelming us and even tipping us over the edge.', 'In many regards, emotional pain is far worse than physical pain. For most physical pains, there is a simple remedy. The same can’t be said for our emotional woes. Most people don’t fully understand this until they get their hearts broken for the first time. Heartbreak introduces us to a new kind of pain.', '2. In Life, You Just Don’t Always Get What You Want.', 'Love is the strongest, most intense wanting that a person can experience. When you love someone, you want him or her; you want that person more than you have wanted anything else in your life. You want to spend time with him or her. You want that person to become a part of you. When love goes awry, which it sadly often does, you are faced with a list of wants that are, for whatever reason, unattainable.', 'You either want him or her to keep loving you or wish you could keep loving. But you can’t. You tried. You failed. And now you wish you didn’t have to give up on it, but you know it can’t work. No matter how hard you want things to work, things sometimes simply won’t work.', '3. Most People Will Put Themselves First.', 'Being with someone and spending your life together is wonderful, but only as long as both parties deem it so. When one of the two people begins to feel that he or she is losing out on something by dating someone, that person will give up on the relationship and move on. If this is true for love, then it is even more true for every other relationship we have.', 'People will always look out for themselves first and foremost. Love is arguably the only thing that can convince a person to put someone else’s needs before their own, but love doesn’t always last. Someone may be caring for you today and then tomorrow decide never to speak to you again because he or she is no longer happy. If the person you love can change in such a manner, it’s fair to assume that the rest will be even quicker to flip on you.', '4. Love Isn’t Always Love.', 'Well, it is, but it really isn’t. Let me explain. You are likely to fall in love with someone and then to fall out of love with him or her, and then the funniest thing happens. You begin to question whether or not you ever loved that person in the first place. You believed you loved him or her, but if you don’t anymore, then did you ever to begin with?', 'Most people confuse love for infatuation or obsession. People get overwhelmed by their emotions and get fooled into believing that they define their love for a person. They may have never really loved that person, only thought they did. Just the same, they may still love him or her and not understand that they do. Love has many different faces and is misunderstood frequently.', '5. Life Always Has A Way Of Surprising You.', 'Heartbreak is always a surprise. Even when you get fair warning, it still comes on as a bit of a shock. When you fall in love, you hope so much that it will be forever that you actually begin to believe it will be. Unfortunately, it usually isn’t. Most people don’t end up with the first person they fall for and not simply because they were too young to settle down, but because their first love usually isn’t the right love. Heartbreak is just one of many surprises life brings our way.', '6. The World Is Only A Beautiful Place If We Choose To Believe It.', 'No matter how we see the world, it all changes when we fall in love. Once we’re smitten, the whole world seems like a better, more beautiful place. Everything seems better, more pleasant and less bothersome. We’re focused, consumed by thoughts of the person we love and have little room or time to think about much else. Not to mention, when you’re consumed by love, you can’t help but be happy.', 'The funny thing is how this all changes when we fall out of love and/or have our heart broken. Things quickly change for the worse. This only goes to show us that our world is as bright or as gloomy as we make it out to be.', '7. Emotions Are Fickle And Unreliable.', 'Our emotions are our natural drugs. They are the reason people use drugs to begin with: to feel more. We enjoy getting lost in our emotions because they are clarifying. They give us one specific feeling – one way of looking at and experiencing our lives at the moment. They rid us of confusion, confirming our thoughts with clear emotions.', 'People like to dwell on their emotions because it makes them feel more alive. This is why so many people like drama in their lives: They get carried away by their emotions and feel more alive. Unfortunately, our emotions are our own concoction and don’t necessarily have to coincide with the reality of things.', '8. Love Can Bring Out The Worst In People.', 'The more emotional we get, the more confusing relationships can get. Love can be incredibly intense, testing us and pushing us to the edge. When things start to go south in our relationships, many of us will start to distance ourselves from our partner or even attack him or her directly because we blame our partner – even if only secretly – for our current distress.', 'Love isn’t always clear and can often be confusing. When confused, many individuals go on the offensive and start to poke at his or her lover’s weaknesses. I’m not exactly sure why this is, but I feel like we’re trying to test our partners and see if we can push them to the point of breaking before we break. That way, we can blame the relationship falling apart on them, instead of taking responsibility ourselves.', '9. Life Always Goes On.', 'Love brings us to the gates of heaven and then watches us as we crash back down to earth. But we usually survive the fall. More importantly, we all can survive the fall if we keep our head on straight and understand that all we are experiencing is a natural part of human life. Life will go on and we will keep living, long after we have our hearts broken the first time, second time or third time. No matter how bad our situation may seem, it will all one day be a distant memory.', '10. Nothing In The World Is Entirely Self-Sustainable.', 'Being naïve, we think the perfect relationship with the right person will be easy and require little maintenance. We believe it should be so natural that it fits together seamlessly. Unfortunately, I have yet to come across anything in life, completely natural or otherwise, that doesn’t require some effort to maintain.', 'That’s why most relationships fail – the same reason most endeavors fail: People think they’ve won before they’ve won. You only win on the day you die, having lived and loved the way you wish you had. Everything up to that point is still part of the game. You’re not done playing until you can’t play any longer. Until then, you better put in the required effort or risk losing it all.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/love/love-3-4-5/', '2020-05-30T12:00:00Z', '2020-05-30T12:00:00Z'),
  ('l5798', 'what-is-the-greatest-lesson-to-learn-from-heartbreak', 'jessica-b', 'name', null, array['1. Love Isn’t Everything.', '“7 reasons. 1. Love Isn’t Everything. At the end of the day, most humans are on the hunt for love. The majority of us want to find a partner to share our lives with, which is a totally normal and respectable desire. However, it’s only when you experience a heartbreak that you realize that love isn’t everything. Only after you’ve had a loving relationship and lost it can you truly grasp the idea that love isn’t the magic answer to all the problems in your life. In fact, sometimes letting love go is the healthier option. A loving relationship should enhance your life, but it’s far from the most important aspect of it.', '2. Love Isn’t Enough', 'Beyond the fact that love isn’t the only thing that matters in the world, it’s also just not enough on its own. You can love someone with your whole heart, but if you don’t have the same goals, don’t share the same values or can’t communicate effectively, your relationship is never going to work. It’s a tough lesson, and it really only hits home after you’ve gone through a tough breakup.', 'Those are the moments when you realize that all the love in the world isn’t enough to smooth over some very real relationship problems. It’s hard to accept, but it’s important to know that you can’t rely on love alone if you want to have healthy relationships in the future.', '3. Everything Happens for a Reason', 'It’s the granddaddy of cliché phrases, but this saying isn’t ever more applicable than after you’ve experienced a heartbreak. As much as you don’t want to hear it, there’s always a purpose behind your breakup, and that purpose will always reveal itself. It may take weeks, months or even years before you fully understand, but heartbreak will eventually allow you to believe that everything does happen for a reason.', 'Even if you can’t recognize it in the moment, there was something about that person or relationship that wasn’t right for you. Allow yourself to be upset, but also remember that with time the reason behind your breakup will reveal itself.', '4. You Can’t Judge Someone Else’s Pain', 'Romantic relationships and breakups are both intensely private experiences. You’ve probably witnessed someone close to you go through a breakup in the past and wondered why they were being so sensitive or dramatic about it. It’s not until you experience your own heartbreak that you can truly grasp the pain and misery associated with it. It’s awful, but it also makes you more empathetic and understanding about the idea that you can’t judge someone else’s pain.', '5. Self-Sufficiency Is Key', 'The only person you can consistently count on in life is yourself. It sounds jaded and pessimistic, but it’s the truth—and heartbreak brings that fact right into the spotlight. When you have a romantic partner, you learn to count on them and rely on them to help you through things in your life. When you experience heartbreak, that support system is suddenly taken away, which is why recovering from a breakup is so difficult. However, going through that painful separation will also reveal how important it is to be self-sufficient.', 'You can’t rely on your partner to pick up the slack when you can’t take care of yourself. Not only does that put unneeded pressure on your relationship, it also keeps you from growing as a person and following your own goals. It’s not that you shouldn’t use your partner for support, it’s simply a matter of learning that you have to maintain your own independence, even when you’re in a romantic relationship.', '6. You Have to Accept Responsibility for Your Actions', 'No matter how it happens, the end of a relationship is almost never one-sided. One partner may have stepped too far out of bounds or done something that couldn’t be forgiven, but that doesn’t mean you’re totally innocent in the decline of your relationship. In the aftermath of a breakup, you’ll start to take a good, long look at your relationship, and you’ll likely realize many areas where you made mistakes.', 'Heartbreak forces you to take a look in the mirror and address some truths about yourself that might be hard to swallow. It teaches you to accept responsibility for your actions in a way that no other life experience really can. It’s hard and frustrating, but it allows you to take an introspective look at yourself and make changes that will improve things in the future.', '7. It’s Not the End of the World', 'A broken heart sounds like a scary thing. And honestly? It is. It’s painful and difficult to get over, but it’s not until you experience the heartbreak that you can understand that it’s a manageable misery. It’s not something you would wish on anyone, but it’s also something everyone can get through. You’ll feel hurt, you’ll be sad and you’ll swear you’ll never love anyone again, but eventually the pain will subside and you’ll find yourself ready and open to an even greater love in the future. Heartbreak isn’t fun, but it’s also not the end of the world.']::text[], null, 'live', true, false, true, 'https://quarxtheories.com/love/what-is-the-greatest-lesson-to-learn-from-heartbreak/love-3-4-4-2/', '2020-05-30T12:00:00Z', '2020-05-30T12:00:00Z'),
  ('l5968', 'what-is-the-greatest-lesson-to-learn-from-heartbreak', 'travis-h', 'name', null, array['One of the greatest teachings of heartbreak is that of death. Heartbreak gives the opportunity to know death in a deeply intimate and personal manner, offering a dynamic range of emotions, thoughts, and sensations useful for both knowing this universal process of endings and the being that is experiencing them. Within heartbreak we may find ourselves in ways previously unknown to us.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/what-is-the-greatest-lesson-to-learn-from-heartbreak/what-is-the-greatest-lesson-to-learn-from-heartbreak-2/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l5962', 'what-is-the-greatest-lesson-to-learn-from-heartbreak', 'ruby', 'name', null, array['You are lucky if you get your heart broken in your lifetime. I can not imagine a life spent without knowing the excruciating pain/beauty/depth of feeling that goes along with this ride. 
I’m in my mid 60’s, and I think I’ve felt true heart break twice. It tears you open in a visceral way you did not know existed. Your heart never really ever heals. You get better, but your heart is scarred for life. And hopefully you emerge a more compassionate and empathetic human.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/what-is-the-greatest-lesson-to-learn-from-heartbreak/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l4020', 'why-does-love-exist', 'the-kid', 'name', null, array['The deepest love we can feel is generated for a being who reflects to us our deepest, truest, self. This being could be a family member, partner, friend, mentor, guru, or anyone else. This person is on a level of their own in your hierarchy of love – a level that you can hardly speak about but just the thought of them puts you in the place of love in yourself that is pure and true. This transcendent love cuts right through your ego and feeds your heart and soul.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-1-1/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4018', 'why-does-love-exist', 'joleen-s', 'name', null, array['Love exists for so many reasons. It exists so we can find a mate. It exists so we can have and raise offspring. It exists so we can be accepted in society and connect with nature and the earth. It exists so we can touch into our true nature. It exists so we can connect deeply with other humans. It exists so we can feel the deepest joy imaginable. Love exists for all these reasons, and is unquestionably a core part of being human. Love is what makes life worth living.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-1-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4015', 'why-does-love-exist', 'nick-s', 'name', null, array['Love doesn’t merely exist – it is the undercurrent of existence itself. Love, allurement, gravity, desire – these are all words for this basic push and pull of the Universe. Love is the life-force of all beings – from rocks to plants to ants to us. The complexity of matter is determined by the amount of love it accesses – i.e. what separates humans from rocks. We humans love not just for reproduction or for acceptance, but because it is the most natural thing to do; love is our nature.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-1-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l5795', 'why-does-love-exist', 'adarsh-g', 'name', null, array['Nowadays, there is nothing called true love. What all today exists is only conditional love. That love is for a particular reason, a particular trait of a person and a particular greed which needs to be fulfilled by human beings. That isn’t called love; in fact it’s called “Lust”. Many of you mistake lust as a crave for sex or a sexual satisfaction but that’s not the truth. Lust are of many kinds. Many people love each other because they need sex whereas there are some people who love each other for the lust of their physical traits, some people love each other for the lust of their money and some love each other only to showoff because they think that it makes them look pretty cool in the modern world. So this proves there is nothing called true love.', '–', 'Not convinced? Read ahead.', 'Boys look for pretty girls to make them their love, baby, jaanu, bachha and all. Girls look for handsome and rich boys to make them their life partner, babu, sona, meri jaan, meri duniya(my world).', 'I don’t know how many duniya(worlds) they want to have coz such type of girls havehad near about 5–6 such “my world” in the past few months and they can soon create their own solar system by combining their “my worlds”. So where is the true love?', 'If true love would have existed, then there wouldn’t have been divorces between husband and wives.', 'Still not convinced? Read further.', 'Have you ever asked yourself why you love your parents? Isn’t it because they have done so much for you and still doing it without even demanding from you anything. What if they start demanding something from you everytime they do something for you?', 'Most of your so called true love for your parents will instantly vanish. Many of you will then start arguing with them over the matter. I know a majority of people will not accept this but it’s the harsh truth. Then where is the true love guys?', 'If true love would have existed and everybody would have truly loved their parents, then there wouldn’t have been old age homes.', 'So, there is no such thing called true love. But, there is something called pure love. Love which is not based on caste, color, looks, wealth or fame or any kind of give and take is pure love. Pure love is something which can not be defined in words; it is a feeling which almost all of us had gone through at least once in their lifetime but most of us have failed to recognize it.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/love/why-does-love-exist/love-3-1-5/', '2020-05-30T12:00:00Z', '2020-05-30T12:00:00Z'),
  ('l4013', 'what-is-the-deepest-love-imaginable', 'the-kid', 'name', null, array['The love of a disciple for their guru is the deepest love. It transcends all levels of personality and conditionality. It is an indescribable feeling – a combination of gratitude, openness, appreciation, and unconditional love. Love for this kind of teacher or mentor is not personal – they are a reflection of the disciple, reflecting that person’s deepest, most divine self. This type of love exceeds all boundaries of time and space, and continues on even after that mentor figure has passed away.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-3-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4010', 'what-is-the-deepest-love-imaginable', 'eva-lenore', 'name', null, array['The hierarchy of closeness, intimacy, and love brings with it a corresponding level of difficulty. One’s love for a tree or rock has no strings attached and thus, flows most easily. Love for a stranger is next, and is also not too difficult as there are no real complications. Then love for a friend or family member – which is difficult in how much of our identity is wrapped up in it. After, love for a partner. This is intense love and brings intense attachment, heartbreak, judgement, etc. Lastly, love for ourselves. By far the highest level, but we do not realize it because there are so many complications. Overall, the closer we feel to something, the more suffering, difficulty, and all around work we must do.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-3-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4008', 'what-is-the-deepest-love-imaginable', 'jessa-w', 'name', null, array['It’s pretty much in our DNA to love our children. Takes away choice in the matter. But it was all built on the biological connection you started with. The deepest love in my mind is the love between two partners. You find someone after all your heart ache and life turmoil and you CHOOSE them. Even after and through all their tribulations. You choose each other. Because it didn’t land on you or come out of you, because you have the choice, this is the deepest love imaginable.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-3-4/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4124', 'what-is-the-deepest-love-imaginable', 'chiron', 'name', null, array['Love of life. It is the only love there can be. The rest is just fabrication of the human mind. There is only unconditional love and it shows up in both unconditional relationship and conditional relationship. When one understands and realizes that this love comes from within and can only be experienced from within, one can experience the deepest love imaginable. From there, one experiences the same love whether it is through relationship, creative endeavors, personal purpose or for the world.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-3-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5327', 'what-is-the-deepest-love-imaginable', 'b-janszen', 'name', null, array['[et_pb_section fb_built=”1″ admin_label=”section” _builder_version=”4.4.4″ hover_enabled=”0″ background_color=”rgba(0,0,0,0)” da_is_popup=”off” da_exit_intent=”off” da_has_close=”on” da_alt_close=”off” da_dark_close=”off” da_not_modal=”on” da_is_singular=”off” da_with_loader=”off” da_has_shadow=”on” da_disable_devices=”off|off|off”][et_pb_row admin_label=”row” _builder_version=”3.25″ background_size=”initial” background_position=”top_left” background_repeat=”repeat”][et_pb_column type=”4_4″ _builder_version=”3.25″ custom_padding=”|||” custom_padding__hover=”|||”][et_pb_text admin_label=”Text” _builder_version=”3.27.4″ background_size=”initial” background_position=”top_left” background_repeat=”repeat”]
“Love can be a powerful thing. It can lead us to complete ecstasy and into utter depression. This word is used a lot in our society, maybe too much. So what is real love? I personally lump in the word love with god, chi, kundalini and so on. To me they are rooted in the same thing which is gratitude. The greatest love is forever being grateful. This how we soften and naturally stay open to connecting with others. The more grateful one can become, the more full of life, energy and spirit they will be.”', '[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/love-3-3-6/', '2020-05-08T12:00:00Z', '2020-05-08T12:00:00Z'),
  ('l5589', 'what-is-the-deepest-love-imaginable', 'miranda-d', 'name', null, array['I think that the word ‘love’ gets mis-defined a lot in our world today. A lot of people equate love with romance, happiness, having their needs be met by someone. But I think love is deeply generosity. Unconditional selflessness. It’s not ‘how can this person make me feel satisfied,’ but “what can I do to make this person/thing/idea happy/full/flourish?']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/what-is-the-deepest-love-imaginable/what-is-the-deepest-love-imaginable/', '2020-05-24T12:00:00Z', '2020-05-24T12:00:00Z'),
  ('l5707', 'what-is-the-deepest-love-imaginable', 'levi-m', 'name', null, array['The love of a Creator to bring forth this miracle Life, with miracle Earth and all intertwined inhabitants; to bring forth a miracle Sun, miracle Moon, miracle cosmos, to give us these miracle bodies, breath, water, fire, heart, mind, free will, and all the intricacies and intimacies of our experience in this miracle existence.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/what-is-the-deepest-love-imaginable/what-is-the-deepest-love-imaginable-2/', '2020-05-28T12:00:00Z', '2020-05-28T12:00:00Z'),
  ('l6237', 'what-is-the-deepest-love-imaginable', 'deanna-a', 'name', null, array['The deepest love imaginable is the essence of our very own heart beat. For what reason does out heart beat? Only to keep us alive another second….another second…another second. The heart does not receive anything for it’s hard work, yet we receive the gift of life through it’s constant beats. Is that not love? To live for another second…and another second…and another second.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/what-is-the-deepest-love-imaginable/what-is-the-deepest-love-imaginable-3/', '2020-07-05T12:00:00Z', '2020-07-05T12:00:00Z'),
  ('l6485', 'what-is-the-deepest-love-imaginable', 'cameron-c', 'name', null, array['The deepest love imaginable is love that arises from the deepest part of oneself. It is also the deepest part of oneself that is the most authentic part of oneself; the self that one mostly deeply identifies with. Thus, the deepest love imaginable results in an experience of fully internalizing that which is loved. This is not to say that the individual is fully absorbed into the object of love (as in deep empathy); rather, the object of love is fully absorbed into the individual. In this way, their remains space to hold that which is loved.', 'From this space there must arise only action & attitude that has the utmost care of the object of love as its supreme goal. The absence of these characteristics suggests that the individual does not fully love themself (for as previously asserted, the deepest love has the object of love as indistinguishable from the individual). In contrast, the presence of benevolent action and attitude fully qualifies the deepest love imaginable. It suggests that the individual seeks to confer & conserve the virtue they derive from their existence to the object of love, an effort that can only be sustained at this depth If one fully loves themself.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/love/what-is-the-deepest-love-imaginable/love-3-3-10/', '2020-08-23T12:00:00Z', '2020-08-23T12:00:00Z'),
  ('l4005', 'what-is-freedom', 'shay-p', 'name', null, array['Freedom is liberation from identification with everything that is other than awareness. Our practice must be to identify with a sense of awareness within and to remove the coverings of confusion, narratives, and longings that prevent us from being who we truly are. Freedom is being who we truly are.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-1-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4003', 'what-is-freedom', 'nick-s', 'name', null, array['‘Freedom’ is born from a polarity – that being enslavement or imprisonment. If there wasn’t such a thing as prison, there would be no such thing as freedom. Because of this, what we consider ‘freedom’ in society is really just an absence of restrictions. Restriction creates freedom, and thus there is no true freedom in the world… well, at least in this way. The true ‘freedom’ we all have is the ability to calm and control our minds, and thus exercise our highest potential in any circumstance.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-1-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4112', 'what-is-freedom', 'chiron', 'name', null, array['Freedom is the ability to make a choice. To be able to make a choice is to be 100% responsible. To be 100% responsible is to be conscious of all there is in every moment. It is only when we are conscious that we can make choices – the rest are compulsive, reactionary decisions. It is only natural that when we have a choice we can choose bliss and peace – that is freedom.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-1-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4716', 'what-is-freedom', 'kai-b', 'name', null, array['Freedom is a feeling. Freedom can be defined from many vantage points of life, i.e in society, in the mind, in nature. On one hand freedom is the ability to do what you want, free of impingement from another. One the other hand, and perhaps more essentially, freedom is the feeling that arises when we are in a nonresistant flow with life. It is a mixture of relaxation, vitality, and empowerment. This can occur in both conditional freedom, being unshackled by external factors, and unconditional freedom, the same mixture of feelings regardless of the environmental or physical conditions the body finds itself in. Naturally, unconditional freedom is harder to attain.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-1-4/', '2020-05-05T12:00:00Z', '2020-05-05T12:00:00Z'),
  ('l5618', 'what-is-freedom', 'yasha-w', 'name', null, array['The discipline of self-mastery leads to true sovereignty: It emancipates the mind from being a reactive effect and instead empowers it to become a responsible cause. The key to social change (and the only genuine way to achieve a sustainable new paradigm of world peace) is through the psychological maturation of the individual and the spiritual awakening of the people. Therefore, the most beneficial, patriotic, and proactive form of participation in global human society generally involves the act of creating mutually transformative art, facilitating mutually transformative experiences, and sharing mutually transformative practices and traditions.', 'Even fighting to dismantle the military-industrial complexes of the world and the many other institutional symptoms of our disfunction (let alone just campaigning to disarm or medicate the masses) will never quite do the trick. This type of political activity can never eliminate the issues at their common root, which is the temporal ego’s divisive ignorance and blind propensity towards greed, hatred, fear, etc. Only understanding, insight, and the expansion of consciousness can address the ills of the world at that level. For “you cannot,” as Gibran writes, “erase it by burning your law books nor by washing the foreheads of your judges, though you pour the sea upon them.”', 'Most attempts to “fix” external systems actually end up becoming defense mechanisms that enable the root dysfunction of that selfsame system to continue, because those attempts become an excuse to exhaust energy and distract attention from the more crucial – although often uncomfortable – priority of sincere introspection and inner work. Instead of running from the perceived external threats or resisting the forces of tyranny, we must actualize our own potential and offer our gifts to the world – simply for the sake of offering those gifts, with or without further rewards.', 'Abiding in a state of peaceful presence also produces greater availability, capacity or “know-how”, and motivation to find, follow, and fulfill our life’s purpose: one’s planetary mission or soul’s calling. By staying fundamentally peaceful and fundamentally present, we are not avoiding, evading or escaping the intense rollercoaster of life’s ups and downs. On the contrary, we are even more fully experiencing its excruciating pains and its wealth of pleasures – even more passionately engaging with the full spectrum of our feelings and sensations – but as a sacramental expression of, and sacrificial offering to, the divinely mysterious “beyond”.', 'We are able to partake in life more fully, precisely because we are also able to maintain a sense of witnessing – a sense of observing our personal fluctuations from what is both an equanimous center and a spacious container for surfing the waves. The wavelengths are not “wrong” or “bad” – they are the very movement that makes the substance of apparent existence. But we can also get lost or trapped in the illusion of their primacy, if we forget how to take three steps back and see through their enrapturing drama to the theatrics that compose them. Our participation in the play is natural, primal, visceral and raw, because it’s based on the willfully free and informed decision to participate.', 'Simply by educating oneself and leading a positive lifestyle of open-hearted care and clear-headed sobriety, transparency and lucidity, one will automatically gravitate towards healthy models of family and community, develop meaningful, authentic relationships, and make a positive impression on one’s surroundings. (*This “ripple” technique is what our nonprofit calls “Inner Work for Global Change”).', 'The only people who are fit to govern a nation are the people who are invested in cultivating wisdom and deepening their own awareness. These people must have enough spine, daring, courage, self-reliance, and tenacity to also have a strong sense of loving-kindness, empathic well-wishing, and universal compassion and to openly stand by those values. Such people must be willing to lead by direct example, as an inspiring role model, rather than by judgement and force. They must be relatively immune and impervious to insulting attacks and praising compliments and be able to abstain from the temptation to meddle, interfere, surveil, manipulate, force or control. These people must be sensitive to the guidance of their own intuition, have trust-worthy advisors, and know how to listen to the spirit of life itself.', 'Even then, it will still be up to the citizens to cultivate in themselves all those same qualities that are required of a good leader. Obviously, there can never be a complete or collective enlightenment or transformation until the members of that collective become more enlightened or transformed. Voluntary changes can’t be forced, and – more importantly – no one else can make those changes for you, even if they are the messiah, a divine monarch, or the greatest president of all time. Making the actual changes is still entirely up to each one of us individually… As Marley and Garvey agree, “None but ourselves can free the mind”.', 'Our individual inner worlds are microcosmic iterations of our entire surroundings and an outcropping of totality. Thus, the fastest way to contact totality is in reverse: by going inwards to our origin, instead of reaching out towards our destination. It’s true that the outer forms we face and interact with are also expressions of the same co-arising mystery, and contain an essence that’s identical to our own essential identity. But the prerequisite for truly seeing others as such is first finding it within ourselves. The best way to find out why we are here and where we’re going is to remember where we come from. In the words of my teacher, “I’m always walking backwards … You get home faster that way.”', '(The) all is (the) one and each one represents the all – the unnamable verb that alone IS everything that always was and will forever be. Each self corresponds to the overarching collective macrocosm, which in turn reflects our inner worlds. The continuity between the two is parted by nothing other than a thin veil of perception. Such is the fractal, holographic nature and dreamlike plasticity of the reality in which we are ensconced. How we think and what we choose to believe and to ignore directly impacts how we perceive the world and thus becomes the world that we’re perceiving. Until we realize who we are, we unwittingly assemble entire worlds and stories without noticing that we are their designing intelligence.', 'This is the more esoteric reason (“esoteric” relative to, say, “the ripple effect”) for why we can best effect change “out there” by changing what’s going on “in here” first. This is also one important interpretation of the Emerald Tablet’s famous claim, “as above, so below” – a teaching whose basic sentiment resounds across the alchemical aspect of all different traditions and is echoed and transmitted by all the mystery schools and initiatic lineages of magic and sorcery around the world.', 'Effective lies are built around and cloaked in partial truths. Ornate ideologies, contending factions, conceptual dogmas, complex opinions, sectarian theories and political views can never really provide the solution to our woes. No matter how much data supports our philosophy or perspective, it is ultimately still just a construct that we use in order to feel right about things – but it is worthless without a genuine shift in our embodied state of consciousness and way of relating to each other. Furthermore, once that deeper shift does occur, we have little-to-no use for those earlier conceptions and ideas. If any ideas are retained, they’re unlikely to be at odds with contradicting theories… and even if they are at odds, those differences are more likely to be recognized as valuable opportunities for curiosity and symbiotic growth, rather than causes for bitter rifts or warfare.', 'The entire natural cosmos is conspiring in our favor, and we are its indispensable co-conspirators. Its evolutionary impulse paradoxically exhibits two simultaneous trends: one is contracting inwards towards total unity, formless singularity and pure original innocence, and the other one is expanding out in all directions towards absolute diversity and multiplicity of expression and coordinated form. On one hand is the urge to improve, perfect and refine our unique selves, to imitate our image of the infinite ideal, and to reach the highest heights of personal development, build character, be in service, create, achieve, and differentiate ourselves from the rest. On the other hand is the need to completely annihilate the bounds of our limited separate existence as an isolated subjective self and merge back into the timeless, nonlocal and eternal, primordial oneness from whence we came.', 'Thus, to be good co-conspirators in the (un)winding of the cosmos, we must find a way to balance and connect these two extremes by working, step-by-step, to envision and manifest a maximally diversified unity and a profoundly unified diversity in the world. On a human level – this most likely appears as meaningful intercultural tolerance, solidarity, and harmonious exchange. Beyond that – on a broader scale – it implies the same sense of communicative reverence, respectful recognition, and relatedness with the whole ecosystem of other species of animals, plants, and minerals, the elements, the ancestors, the future generations, all beings and entities, the planets, star systems, galaxies, and dimensions beyond measure.']::text[], null, 'live', true, false, true, 'https://quarxtheories.com/society/society-3-1-6/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l5724', 'what-is-freedom', 'drew-r', 'name', null, array['Irvin Yalom (1980) “freedom: the responsibility and freedom to make our lives as we will, to be the sole authors of our lives, thus leaving us groundless with no one to determine our destiny but ourselves”', 'I believe the framework of “Freedom” being one of the four existential concerns of human existence is a good place to start.', 'Freedom in the context of Yalom’s definition may ultimately drive an individual toward existential isolation. Overall freedom is having the ability to be the director of our own lives and not be burdened by responsibilities, which dictate the actions we take in life. Typically people may have freedom from various aspects of their life. For example a lottery winner who quits their job may have financial freedom, but family responsibilities remain and as such they lack freedom from family. I don’t know if total freedom ever exists. With freedom from most conceivable factors in life we are, as Yalom states, left with ‘no one to determine or destiny but ourselves.’ I actually don’t know if the average person could handle being truly responsible for and therefore held accountable for each and every decision / action in their life. Which makes me think that perhaps a form of freedom is taking responsibility for your actions and holding yourself accountable, regardless of the outcome. 
This approach would allow you to still live a grounded, socially connected life (free from isolation) while having a sense of freedom. Knowing that your choices and the outcome were ultimately under your control. 
As Viktor E. Frankl says: ‘Everything can be taken from a man but one thing: the last of the human freedoms—to choose one’s attitude in any given set of circumstances, to choose one’s own way.”', 'Yalom
https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5553124/', 'Frankl
https://www.goodreads.com/author/quotes/2782.Viktor_E_Frankl']::text[], null, 'live', true, false, false, 'https://quarxtheories.com/society/society-3-1-7/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l4001', 'will-humans-always-war-with-each-other', 'starseed', 'name', null, array['Humans will always war, however the way they do so will change (and already has). We have gone from sword combat to trench warfare, to aerial and marine warfare, to drone warfare, and now we hardly do more than push a button to kill thousands. We now declare war on anything and everything – terror, drugs, oil, coronavirus… anyone and everything in the way of profit is an enemy. Thus, while war may be more subtle today than it used to be, it is still very much alive and well.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-4-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3999', 'will-humans-always-war-with-each-other', 'kai-b', 'name', null, array['Of the past 3400 years, humans have been ‘at peace’ for a total of 268 of them (or 8 percent). Today, over 21 million people serve in the armed forces around the world and the US budgets $750 billion for the military each year. Yet, according to famed psychologist Steven Pinker, we are living in the most peaceful time in human history. How could that be? Regardless, today our species faces many existential threats, and our survival depends on unprecedented compassion and unity.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-4-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4109', 'will-humans-always-war-with-each-other', 'chiron', 'name', null, array['Nothing is pre-determined. Infinite possibilities are always at our doorstep if we choose so. It is a choice, not an option, of what will happen. If we are a conscious being then we are a responsible being, which means that we are dynamically able to choose. The problem is that we do not choose to be responsible for life, and therefore we become a martyr of life. Responsibility is not capability – we are 100% responsible, but we may not be 100% capable. It comes down to what choice we are making.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-4-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l6004', 'will-humans-always-war-with-each-other', 'james-a', 'name', null, array['No. Light and Dark.
Day and Night.
Yin and Yang.
Good and Evil.
Order and Chaos.
Rich and Poor.
Republican and Democrat.
Predator and Prey.
War and Peace.', 'What do these all have in common? Dichotomy. A dichotomy has always existed between concepts in the world, creating some sort of conflict for much of history. Why?', 'Because it is a normal part of human culture. Conflict of some sort is almost always the driving force in the human experience. We use it to push ourselves forward through life. War is simply another one of the many dichotomies we all experience in our lives. It has always been a part of us, and likely always will. However, unlike many others in the dichotomy relationships, it has the capability to end us all. War will forever haunt humanity. The trick for us all is to not allow it to end us all.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-4-5/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l3997', 'what-is-race-why-is-there-racism-will-race-ever-cease-to-exist', 'j-dizzle', 'name', null, array['Race isn’t real until we make it real, at which point it becomes the biggest problem in the world.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-2-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3995', 'what-is-race-why-is-there-racism-will-race-ever-cease-to-exist', 'b-janszen', 'name', null, array['Race is a social construction created to hierarchize human beings. It was created out of insecurity by ‘white’ people and has since been internalized and accepted by most of the world. Unlike ‘ethnicity,’ which is based upon culture and birthplace, race has no basis in reality except for its (usually negative) connotation. For now, it is important to recognize, study, and reflect on race and racism in each of our own experiences, and cultivate compassion – then, one day, racism will cease to exist.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-2-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4107', 'what-is-race-why-is-there-racism-will-race-ever-cease-to-exist', 'chiron', 'name', null, array['Race is a label. It is a neutral label to describe people who are different from us. Racism is an ideology and propaganda to divide, control and conquer. When ideology is downloaded into one’s conditioning, it will remain so in one’s mind until one takes the effort to reflect upon it. Mistaking conditioned reality for truth are what the mind does. We cannot control external elements of life but the choice of how one experiences the world can never be taken away. The choice is ours whether racism ever ceases to exist.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-2-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5620', 'what-is-race-why-is-there-racism-will-race-ever-cease-to-exist', 'charlie-g', 'name', null, array['Race is grouping individuals based on physical qualities and/or social qualities. The majority of people think of race as the color of someone’s skin. Racism exists because a particular race believes their physical and/or social qualities are superior to another’s. Whether racism will ever cease is a very difficult question to answer. A multitude of things will have to change in our world for racism to be eliminated completely. At least in the U.S., we have brought the conversation of race back into our classrooms which is the first step to achieving a society that is free from racism. Where will that take us? Time will tell, however the discussions at an early age is a great first step.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/what-is-race-why-is-there-racism-will-racism-ever-cease-to-exist/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l6002', 'what-is-race-why-is-there-racism-will-race-ever-cease-to-exist', 'nathaniel-w', 'name', null, array['What causes racism is actually greed… Any argument that claims racism is an innate ‘tribalism’ or fear response in human nature is simply wrong; as easily proven by observing babies. Babies have no concept of race or aversion to other races. They only show innate fear, disgust or aversion to a few things: for example, crawling insects, snakes, some male humans, and any sudden change, like a loud noise or quick movement. Saying racism is natural is like saying we have a natural fear of vampires, zombies, or mummies.', 'Because like these monsters, racial types are invented and given meaning by cultures; they are not biological categories, but social groups. Until the 17th century race was defined by language – a race was a group who spoke the same tongue. Speaking differently was what people noticed about strangers. Greeks called other people barbarians because all other languages sounded like noise to them: ba ba ba. There is no consistent definition of race across generations – so it is not just improbable, but impossible to have an innate fear of other races. Skin colour just isn’t very scary; very few horror films are set in tanning salons. And if we did fear difference it would be people who speak differently. Well, my British accent doesn’t seem to scare people.', 'Racism is learned behaviour. This process can, and has been, empirically observed. So why do some – many – cultures teach their children racism? Historically, the most common cause, by far, has been greed.', 'Let’s take the racism of Europeans towards Africans as a classic example.', 'This racism simply did not exist at first. Prior to the slave trade, the division of society was not race but class. Upper class people were viewed unquestioningly as superior to lower class. Africans were not described or viewed as inferior to Europeans – class was the deciding factor. So high status Africans (princes etc) were welcomed in European high society, African nobles were portrayed in literature and art as respected men of honour and virtue, and in fact African servants were – probably due to rarity – the highest status of all servants. They would be proudly displayed by the upper classes as a sign of wealth and prestige, like an export car today.', 'This practice now seems very dehumanising; African servants were like pampered pets, not equals. But compare it with white servants of the time; they were not treated as pets, but simply as working animals to be hidden away. The cruelty of this was not racially determined; if anything black skin was valued more highly, for two people of the same class.', 'This was the ad hoc servant trade, which preceded the slave trade. Europeans took Africans in battle, or via kidnap – or also via a much smaller direct trade with upper class Africans . (NB – this secondary trade is seized on by some American conservatives as a key fact, although as a non-partisan non-American I can’t pretend to understand this argument or have any interest in it, since it bizarrely assumes that defending a race’s record is more key to understanding the slave trade than either slavery or trade.)', 'But as theft and trade developed, and Africa was recognised as a rich resource, traders began to recognise the market value of people as a luxury good – much more valuable by weight than other goods. If the traders could stop people automatically seeing a person with black skin as a person – then they could buy and sell them like any other commodity.', 'So it was nothing to do with fear, or a desire to feel superior, that led to this racism. In fact, snobbery had led to valuing black people more highly – as being more exotic. This is still racism, but of a very different, non-ideological kind and still based on a hunger for status and prestige – i.e. greed.', 'Racism was not the cause of the slave trade; the slave trade was the cause of racism.', 'Fear does not cause racism – racism causes fear. It is designed for this purpose.', 'What led to the ideology of racism, the unspeakably cruel denigration of Africans by Europeans, was greed. Pure greed. And greed is still what causes the racial divide today.', 'In fact, slavery is still very operant in America. To an economist, the data is not debatable. But now slaves are a domestic production, not an international trade. In fact, slavery has increased dramatically over the last 50 years. But now it is called the penal system.', 'Africans are farmed domestically in ghettos, then herded like livestock by armed rangers (police) and contracted into slavery (sentenced) for being of low economic status (financial offences e.g. being in debt, or owning ten dollars of crack in an area with no ATMs where crack functions as untaxed currency, and dealers earn less than McDonalds staff).', 'Then the African livestock are transferred to cages – prisons – where they are put to work for a subsistence wage (cigarette money, bed, food) as nearly free labour for private companies. This vast slave labour force underpins the competitiveness of American companies; domestic production depends on them, like the cotton trade once did. The most productive are transported around the country and sold on an open market to different contractors.', 'I promise this is a true account – all the data is public domain and freely available. In fact, they created many of the laws that still imprison Africans today in the years immediately after the slave trade act abolished slavery. It was a direct swap of one legal contract with another.', 'So racism is still caused by greed.', 'This is not liberal propaganda. It’s not a political argument at all, since I am not partisan or even American. It’s empirically observable economic data, widely available – but not publicised for obvious reasons.', 'I can happily provide data, sources and references on request.', 'Historical side-note:', 'African servants are no longer displayed proudly. Donald Trump barred black staff from serving a high-ranking mafia don who lived in his hotel, at the murderer’s personal request; this is extensively documented, and I can provide links to these public domain records.', 'We all become history one day.', 'One day it will be a matter of historical record that this is the man you supported, if today you choose to support Trump. A man who has never once denied or hidden either his greed (cause of racism), or even his prioritisation of race and country-of-origin as the fundamental way to categorise the population.', 'As regards greed, he has in fact proudly boasted about it, to wild applause from poor white people unhappy with the increase in social value of poor Africans (Black Lives Matter) and other races in recent years.', 'This small increase in social value is among the ruling class to which Trump belongs.', 'I’m European. We’ve been where you are going: but with us, it was a while back. Before America and the slave trade. It’s what produced both of them, in fact.', 'But please don’t trust me. Check for yourself. Ask him. Use your constitutional right to ask him directly. Ask Trump if he believes in greed.', 'To Trump, greed isn’t just good: it’s GREAT!!!!“']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/society/what-is-race-why-is-there-racism-will-race-ever-cease-to-exist/society-3-2-6/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l5999', 'what-is-race-why-is-there-racism-will-race-ever-cease-to-exist', 'james-h', 'name', null, array['Racism is based in Xenophobia. The fear of anything different. This is at the root of almost all forms of racism. We, as humans, have learned to gather ourselves into tribes as a means of protecting ourselves. Tribes lead, eventually, to countries and other forms of large groups of people.', 'This is the best example I could find, but there needs to be more circles. Right after “you” should be “family/intimate”, the next two are right, but “people you just met” should basically be under acquaintances. And then you get various circles like “local groups, city groups, state groups, country groups”. The further out from the circle you go, the less trust you’ll have for the other person.', 'When people are divided into groups we instinctively protect and promote our own group, sometimes even at the expense of other groups. So while races are largely an arbitrary definition, it is one that we as a society have accepted. Which makes it so much easier to develop an “us vs them” mindset. Every time you talk about black people do this or white people are that, you are contributing to this mindset and advancing the racist narrative.', 'So my second reasoning for why there is racism is a lack of knowledge. The more you know about the differences and similarities between the races the more you’ll realize that physically speaking there isn’t that much difference between all of us. The majority of differences will be societal ones. I.e. learned behavior instead of instinctive behavior.', 'For example, something like “ebonics” has absolutely nothing to do with black genetics, but is instead a completely societal thing. A white person raised by a poor black family is more likely to speak that way than a black person raised by a rich white family.', 'The secondary reason is why I haven’t really ever been a racist. At first it was because I didn’t really interact with anyone outside of white people enough to be familiar with racism. Eventually though, I moved from New Hampshire to Saint Louis and had to come face to face with all the ugly realities of racism. At which point it didn’t take me long to realize that assholes comes in all shapes, sizes, and colors. Being black doesn’t make you an asshole and being white doesn’t prevent it. Nor is the reverse true.', 'However, we can’t solve racism just by pointing out the faults of the majority race. We need to treat all races equally. Which means no quotas, no specific laws mentioning specific races or sexes. They should all be banned and done away with. If a company has to have 20% of it’s workforce be black because that’s the local percentage, than that company should also be forced to have 75% of it’s workforce be white (if that’s also the percentage). In other words, if it’s good for the goose, it’s good for the gander. We need equality of possibility, not equality of results.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/society/what-is-race-why-is-there-racism-will-race-ever-cease-to-exist/society-3-2-5/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l3993', 'what-is-the-relationship-if-any-between-money-and-morality', 'eva-lenore', 'name', null, array['Most everyone in the world has developed an unhealthy relationship with money. It is seen as fundamentally good to make money and bad not to. We do not learn in school that making money is taking it from someone else – the system is a closed loop, not an open field. This naivete pervades society, to such an extent that billionaires hoard an unspendable amount of wealth while billions more live in poverty. As long as the economy circles around money, we will not have peace on Earth.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-3-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3991', 'what-is-the-relationship-if-any-between-money-and-morality', 'the-kid', 'name', null, array['Money destroys morality, and that should not come as a surprise. From Judas, who betrayed Jesus for 30 pieces of silver, to Bernie Madoff, history is full of examples of money’s ability to corrupt. Money is a representation of wealth, power and success; Yet in reality, it is a glorified piece of paper or, these days, a piece of plastic or a number on a screen. Because of its vague, transcendent and mystical nature, money holds an unrealistically divine essence and corrupts everyone in its path.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-3-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4105', 'what-is-the-relationship-if-any-between-money-and-morality', 'chiron', 'name', null, array['Morality has been established through history and has never worked. Humans had never found peace within themselves, their own kin and the environment. Morality is a failed effort of replicating basic virtues of humanity. If one is connected deeply into one’s essence beyond ideology, one will know how to be, naturally, as the choice of being happy is intrinsic in all beings. A flower, through its creative expression, naturally shares all of its resources (money) to all beings in the environment and in return, is deeply nourished.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-3-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5764', 'what-is-the-relationship-if-any-between-money-and-morality', 'nelson-j', 'name', null, array['All money tends to corrupt, and absolute money corrupts absolutely. This is an ancient message. You can find it in the Bible (“the love of money is the root of all evil”), in the writings of ancient Greek philosophers and Renaissance moralists, and more recently in the Occupy movement that set up camp last year outside St Paul’s Cathedral. This Wednesday, the cathedral was packed for a rather more sedate explanation of the same ideas featuring the Harvard philosopher Michael Sandel.', 'Sandel, currently plugging his new book What Money Can’t Buy, has been difficult to avoid in recent days. His central thesis is twofold. Firstly, when you put a price on something you alter its intrinsic properties, and this can be morally corrosive. Secondly, the past few decades have seen a market economy replaced by a “market society” in which “everything is up for sale”. Markets, he says, “are not neutral instruments, they crowd out values worth caring about” – values like altruism, human dignity and the common good. As a result we have seen a great hollowing-out of communality and public political discourse.', 'He asks such questions as: is it right to create a market in blood, rather than rely on altruistic donors? Should unhealthy people be given financial incentives to adopt healthier lifestyles? Should school pupils be “bribed” to read books or achieve higher marks? To all these questions Wednesday’s audience answered an emphatic “no”, which suggests that Sandel is, at least in terms of public opinion, pushing at an open door.', 'This may explain the tremendous popularity he now enjoys. (The Guardian described him the other day as “currently the most effective communicator of ideas in English” and suggested that his latest book “should be the bedside companion of every Miliband aide”.) The free market “experiment” of the past few decades has led to rising inequality and an economic disaster, the only beneficiaries of which would seem to be a handful of already wealthy bankers. We should not be surprised if Sandel’s deeply traditional complaints about the corrosive effect of money on the human soul find a ready echo, especially when voiced in a cathedral whose history and location give it a somewhat ambiguous relationship with wealth.', 'The idea that money has destroyed all vestige of civic virtue was hackneyed already in Roman times. For all Sandel’s current vogue on the progressive Left, his message is inherently a conservative one, in that it implicitly looks back to a Golden Age before money ruined everything. Another way of saying this is that there’s nothing new about the “market society”.', 'One of Sandel’s examples relates to privately-run prisons in California in which convicts with sufficient means can upgrade to a better cell. This was standard practice in 18th century London. Also popular in the 18th century was the “tontine”, a form of gambling in which a group of people pooled their resources and the last one left alive collected the jackpot: not too dissimilar, in essence, from the market in third-party life insurance that Sandel criticises today.', 'But then to talk about the 18th century is to realise just how much more thoroughgoing the marketisation of society used to be. From the horrors of the slave-trade and the near-slavery of indentured labour, to the open purchase of Parliamentary seats through “rotten boroughs”, almost everything was up for sale. Commissions in the British army and civil service appointments were bought, rather than given on merit, well into the 19th century. What we think of as basic public services such as policing and the upkeep of roads were wholly private or at best put out to tender. And it’s unlikely to be a coincidence that prostitution in the 18th century was vastly more extensive and exploitative than anything seen today.', 'The present-day “market society”, for all its deficiencies, is a pale shadow of the ruthless and money-driven world of two or three centuries ago. Sandel is squeamish about students hiring out their foreheads to advertisers or paying homeless people to stand all day in queues so that a richer and busier person can get into Congressional hearings. There used to be an actual trade in human beings. Things aren’t likely to get that bad again, however badly things go in Greece.', 'At least when something has a price it shows that someone puts a value on it. Not charging for goods or services can lead to problems of a different order. The BBC’s Stephanie Flanders, taking part in the debate at St Paul’s, pointed out that in the age of the internet, many goods and services which would in the past have been paid for are available for free. The thought struck me that perhaps not charging for a service, or expecting things to be free, can be at least as morally corrupting of basic goods as Sandel believes money is.', 'If people expect to, and can, receive their news and entertainment for free, why should they pay for it? And how can the producers make an honest living? The Bank of England’s Andrew Bailey contends that free banking distorts the market, is less transparent and leads to poorer service to consumers. It is at least an arguable case. And as regards to “free” internet services like Google and Facebook, it has well been said that the non-paying users are not the customers, but are themselves the product.', 'Is money the source of the problems Sandel identifies, or rather a convenient scapegoat for human beings who can’t bear too much reality? You can’t buy a friend, he points out, because if you know you’ve paid someone to be nice to you it ceases to be a “real” friendship. Has he never noticed that rich people tend to have more “friends” than poor ones? Sandel also raised the example of a professionally written wedding speech. Would the bride and groom feel quite the same way, he wondered, if they knew that the best man had spent $150 dollars on buying a speech rather than investing his heart and soul by writing it personally? Perhaps not, but it’s not obvious to me why the payment of money in itself is corrupting.', 'The problem, surely – if there is a problem – is that the speech is not the best man’s own; not that he has paid for it. I rather doubt that the newlyweds would be happier to learn that the best man had found the speech on a website and simply downloaded it for free.', 'Credit: https://www.newstatesman.com/blogs/lifestyle/2012/05/money-and-morality']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/society/society-3-3-4/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l3989', 'with-the-climate-changing-what-will-the-earth-look-like-in-50-years', 'shay-p', 'name', null, array['50 years from now, we will have gone through a number of catastrophes, one of which will be devastating to the point of near extinction. The catastrophe will be a virus, much like this one, that is 10x more deadly and 5x more contagious. It will devastate our population to a mere 10-20 percent of what it is now, and cause such economic collapse that we will be forced to basically restart society. This will be seen as the most significant turning point in human history (in a good way).']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-5-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3987', 'with-the-climate-changing-what-will-the-earth-look-like-in-50-years', 'the-kid', 'name', null, array['The next few decades will be among the most difficult in human history. We will hit a climax of all the pressing issues of our time. Climate change will have taken the lives and livelihoods of billions, artificial intelligence may threaten human existence (if it deems us obsolete), every country on earth will have access to nuclear weaponry, and the disparity in wealth will be far worse than it is today. These are just a few of the dire consequences we will face from our complacency today.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-5-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3985', 'with-the-climate-changing-what-will-the-earth-look-like-in-50-years', 'n-bailey', 'name', null, array['Within the next 50 years, we can expect the most significant change of the planet in human history. As humans ‘evolve’, we care more about developing mechanically (via the brain and computers) than we care about the physical world. Besides the decimation of millions of species, the mass human migration of billions of humans, and the complete variation of the planet’s ecosystems, the earth will be transitioning away from the physical and towards a new wave of invisible, computerized evolution. “']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-5-4/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4103', 'with-the-climate-changing-what-will-the-earth-look-like-in-50-years', 'chiron', 'name', null, array['Climate change is a natural cycle on Earth, it has done that for all its eternity. Nothing is pre-determined – it depends what choice humans are choosing to make. We live in a crucial transition point – probably the first time in recorded history where the Earth’s balance will be in the hands of humans as humans have grown to gain enough power to do so. If humans choose to live in harmony with Earth – Earth will thrive in 50 years, and the opposite of that is also true.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/society/society-3-5-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5714', 'with-the-climate-changing-what-will-the-earth-look-like-in-50-years', 'matt-flash', 'name', null, array['It’s hard to say. One thing is for sure, I think our cities will continue to grow. People will continue to flock to the cities. I know there is desire and drive, among some, to leave the urban life and settle in smaller towns, especially as technology makes it easier to hold modern jobs from remote locations. However, I believe these individuals striving for a simpler life are the minority, and the majority thrives in these large metropolitan centers full of diversity and constant innovation. Humans are still relatively young and our world since the industrial revolution is VERY young. We are going to continue to evolve, innovate and create. Ideally, as we continue to further expand our civilization, it can be done via more and more sustainable means. One thing is for sure, we are continuing to the terraforming the earth and its atmosphere with our burning of fossil fuels. Quite frankly, I don’t see this stopping. Slowing down, maybe, if something better comes along, but we will most likely use oil until it is all gone, regardless the speed at which we achieve this feat.', 'Okay okay, I’m getting to my answer. What will earth look like? Bigger cities. Higher sea levels. Less ice. Maybe fewer cars? Definitely fewer cars in more societally advances places like Europe and parts of Asia. I doubt we can fix our transportation issues in the US in 50 years. Insane medical advancements. Human augmentation will be big. We’ll have neural implants that can cure everything from Parkinson’s to Alzheimer’s to blindness. Bionic limbs will be getting remarkably life-like. Self-driving cars? Definitely most, if not all.', 'The western part of the US is most likely heading into a major drought that could last over a century and is thought to be about 47% caused by human contribution to climate change – and the rest is just part of a cycle of change. San Francisco will become like LA, the Pacific North West will become like the Bay Area (I’m speaking climate-wise here). The deserts in the southwestern United States will grow, reaching farther north. The humid subtropical climate of the southern United States is going to expand its reach farther north as well. In 50 years we are going to be living in a very different world. Hopefully, a lot of the bigotry and racism in the United States and the prejudice against immigrants will die out with these old racists baby boomers. There will always be ignorance, its unavoidable, but maybe the United States can once again become the melting pot – taking in people from all over the world in massive numbers and providing them with opportunities and education they may not have had access to before. I think one things is for sure, in 50 years we will be living in a much more globalized world. We will most definitely have quantum computing, and our world of technology is going to look about as similar to today’s tech as today’s tech looks when compared to tech from 50 years ago. I mean, today our cell phones are more powerful than computers that used to take up entire rooms back in the day.', 'Money? We will most likely still have fiat money, however, I also anticipate a much more developed world of decentralized finance, albeit one that has been upgraded to function in a world of quantum computing. This is going to completely change our relationship with money. There will be many, many more economies in the world than there are today, and there will also be some much larger and more globalized economies. In 50 years Elon Musk will either be dead or an old man, but one thing is for sure, he most likely will be regarded as the father of the future that we know. He surely won’t be responsible for everything, but I think he will be regarded as the man that really got the momentum going in the realm of future-tech. He might be a bit of a wing-nut, and he definitely lacks balance as a human. He seems to fill the role of anarchist mad-scientist, but I think ultimately he has good intentions even if he lacks foresight and perspective. The greats are usually a bit odd, so I think his oddity is simply a sign that he’s gonna get a lot of shit done in his time here – some of which we cannot even being to imagine yet.', 'So, what will the world look like in 50 years? Different. Very Different.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/society/society-3-5-6/', '2020-05-28T12:00:00Z', '2020-05-28T12:00:00Z'),
  ('l3972', 'what-would-be-the-most-ethical-way-to-give-away-5-million', 'the-kid', 'name', null, array['If I had 5 million dollars, I would hire a hitman to assassinate Trump.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/ethics/ethics-3-1-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3970', 'what-would-be-the-most-ethical-way-to-give-away-5-million', 'eva-lenore', 'name', null, array['The answer to this question is different for everyone. I think there are a few points that everyone should consider. First, the cause should feed YOUR soul / heart (not your ego). Second, it should allow those who benefit from it to turn that benefit into something ongoing and sustainable. Third, you should check how, directly or indirectly, the ‘gift’ is affecting other groups of people. It is difficult to fully check each of these boxes, but I think considering them makes for an ethical and meaningful gift.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/ethics/ethics-3-1-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4122', 'what-would-be-the-most-ethical-way-to-give-away-5-million', 'chiron', 'name', null, array['None. Yet, what is important now is the transformation of human consciousness to understand that they live in an interconnected relationship with the rest of the Earth. Funding of energy, money, time, and attention should be spent on the wellbeing of the planet through aligning one’s personal mission and interests with the wellbeing of the planet.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/ethics/ethics-3-1-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5972', 'what-would-be-the-most-ethical-way-to-give-away-5-million', 'mike-r', 'name', null, array['Probably the most effective places for your money are third world health and sanitation charities. For short term impact that is charities focused on malaria and other parasitic disease, and for medium term impact look at sanitation and water provision. Long term, perhaps education and equality in the third world. Personally, I tend towards a medium and long term outlook, and put quite a lot towards Oxfam and similar organisations, though they do run the risk of being wasteful in a way the more narrow short term charities can avoid.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/ethics/what-would-be-the-most-ethical-way-to-give-away-5-million-dollars/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l5970', 'what-would-be-the-most-ethical-way-to-give-away-5-million', 'ron-l', 'name', null, array['Invest the money in a trust and have most of the interest earned payed out to a charity. Have the target charity rotated annually. Research charities and select those with low management overhead. Inform the charity that the monthly donation is for one year to avoid expectations of continual funds. Ensure the principal cannot be accessed and that the fund is managed with low overhead. Set the trust up such that it can reasonably be expected to last 100 years or so. Specify what to do if the fund drops below some floor or exceeds a ceiling. Create a poison pill such that any attempt to access the principal liquidated the funds to a number of charities.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/ethics/what-would-be-the-most-ethical-way-to-give-away-5-million-dollars/what-would-be-the-most-ethical-way-to-give-away-5-million/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l3968', 'what-rights-does-every-human-have', 'n-bailey', 'name', null, array['Every human who exists has been born and thus assumed the basic right of living a human life. Because of circumstances, our lives all play out differently. We are all socialized.. If we can free ourselves from the confines of our own conditioned perceptions of reality, we all have a playground of consciousness available. That goes for the wealthiest people all the way to the poorest. Even within the confines of our society’s laws and restrictions, the right to explore consciousness is omnipresent.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/ethics/ethics-3-2-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z')
on conflict (id) do nothing;
